import prisma from "@/lib/prisma";
import Link from "next/link";

async function getBerita() {
  return prisma.berita.findMany({ orderBy: { createdAt: "desc" }, take: 50 });
}

export default async function AdminBeritaPage() {
  const berita = await getBerita();

  return (
    <div>
      <div className="flex items-center justify-between mb-8">
        <h1 className="text-3xl font-bold text-emerald-400">Berita</h1>
        <Link href="/admin/berita/tambah" className="bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2 rounded-lg transition">
          + Tambah
        </Link>
      </div>
      <div className="bg-black/40 border border-emerald-500/20 rounded-xl overflow-hidden">
        <table className="w-full">
          <thead className="bg-emerald-900/20">
            <tr>
              <th className="text-left px-6 py-3 text-emerald-400">Judul</th>
              <th className="text-left px-6 py-3 text-emerald-400">Kategori</th>
              <th className="text-left px-6 py-3 text-emerald-400">Published</th>
              <th className="text-left px-6 py-3 text-emerald-400">Aksi</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-emerald-500/10">
            {berita.map((item) => (
              <tr key={item.id} className="hover:bg-emerald-900/10">
                <td className="px-6 py-4 text-emerald-100/80">{item.judul}</td>
                <td className="px-6 py-4 text-emerald-100/80">{item.kategori}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded-full text-xs ${item.published ? "bg-emerald-600/20 text-emerald-400" : "bg-gray-600/20 text-gray-400"}`}>
                    {item.published ? "Ya" : "Tidak"}
                  </span>
                </td>
                <td className="px-6 py-4">
                  <Link href={`/admin/berita/${item.id}/edit`} className="text-emerald-400 hover:text-emerald-300 text-sm">Edit</Link>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

export default function TambahBeritaPage() {
  const router = useRouter();
  const [formData, setFormData] = useState({
    judul: "",
    isi: "",
    gambar: "",
    kategori: "berita",
    published: false,
  });
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);

    try {
      const res = await fetch("/api/admin/berita", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (res.ok) {
        router.push("/admin/berita");
      } else {
        alert("Gagal menambah berita");
      }
    } catch (error) {
      console.error("Error:", error);
      alert("Terjadi kesalahan");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div>
      <h1 className="text-3xl font-bold text-emerald-400 mb-8">Tambah Berita</h1>
      <form onSubmit={handleSubmit} className="bg-black/40 border border-emerald-500/20 rounded-xl p-6 max-w-2xl space-y-4">
        <div>
          <label className="block text-emerald-200/70 text-sm font-medium mb-1.5">Judul</label>
          <input type="text" value={formData.judul} onChange={(e) => setFormData({ ...formData, judul: e.target.value })} className="w-full bg-black/40 border border-emerald-500/30 rounded-lg px-4 py-2.5 text-emerald-100 focus:outline-none focus:border-emerald-400" required />
        </div>
        <div>
          <label className="block text-emerald-200/70 text-sm font-medium mb-1.5">Isi</label>
          <textarea value={formData.isi} onChange={(e) => setFormData({ ...formData, isi: e.target.value })} className="w-full bg-black/40 border border-emerald-500/30 rounded-lg px-4 py-2.5 text-emerald-100 focus:outline-none focus:border-emerald-400" rows={5} required />
        </div>
        <div>
          <label className="block text-emerald-200/70 text-sm font-medium mb-1.5">Kategori</label>
          <select value={formData.kategori} onChange={(e) => setFormData({ ...formData, kategori: e.target.value })} className="w-full bg-black/40 border border-emerald-500/30 rounded-lg px-4 py-2.5 text-emerald-100 focus:outline-none focus:border-emerald-400">
            <option value="berita">Berita</option>
            <option value="pengumuman">Pengumuman</option>
          </select>
        </div>
        <div className="flex items-center gap-2">
          <input type="checkbox" id="published" checked={formData.published} onChange={(e) => setFormData({ ...formData, published: e.target.checked })} className="w-4 h-4 rounded border-emerald-500/30 bg-black/40 text-emerald-600 focus:ring-emerald-500" />
          <label htmlFor="published" className="text-emerald-200/70 text-sm">Publikasikan</label>
        </div>
        <div className="flex gap-3 pt-4">
          <button type="submit" disabled={saving} className="bg-emerald-600 hover:bg-emerald-500 text-white px-6 py-2.5 rounded-lg transition disabled:opacity-50">{saving ? "Menyimpan..." : "Simpan"}</button>
          <button type="button" onClick={() => router.back()} className="bg-gray-700 hover:bg-gray-600 text-white px-6 py-2.5 rounded-lg transition">Batal</button>
        </div>
      </form>
    </div>
  );
}

