"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";

interface Jadwal {
  id: string;
  tanggal: string;
  lokasi: string;
  provinsi: string;
  imsak: string;
  subuh: string;
  terbit: string;
  dhuha: string;
  zuhur: string;
  ashar: string;
  maghrib: string;
  isya: string;
}

export default function EditJadwalPage({ params }: { params: { id: string } }) {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState<Jadwal>({
    id: params.id,
    tanggal: "",
    lokasi: "Jakarta",
    provinsi: "",
    imsak: "04:30",
    subuh: "04:45",
    terbit: "06:00",
    dhuha: "06:30",
    zuhur: "12:00",
    ashar: "15:00",
    maghrib: "18:10",
    isya: "19:20",
  });

  useEffect(() => {
    fetchJadwal();
  }, [params.id]);

  const fetchJadwal = async () => {
    try {
      const res = await fetch(`/api/admin/jadwal/${params.id}`);
      if (res.ok) {
        const data = await res.json();
        setFormData({
          ...data,
          tanggal: new Date(data.tanggal).toISOString().split("T")[0],
        });
      }
    } catch (error) {
      console.error("Error fetching jadwal:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);

    try {
      const res = await fetch(`/api/admin/jadwal/${params.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

    if (res.ok) {
      router.push("/admin/jadwal");
    } else {
      alert("Gagal mengupdate jadwal");
    }
  } catch (error) {
    console.error("Error:", error);
    alert("Terjadi kesalahan");
  } finally {
    setSaving(false);
  }
};

