async function getKegiatan() {
  return prisma.kegiatan.findMany({ orderBy: { tanggalMulai: "desc" }, take: 50 });
}

export default async function AdminKegiatanPage() {
  const kegiatan = await getKegiatan();

  return (
    <div>
      <div className="flex items-center justify-between mb-8">
        <h1 className="text-3xl font-bold text-emerald-400">Kegiatan</h1>
        <Link href="/admin/kegiatan/tambah" className="bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2 rounded-lg transition">
          + Tambah
        </Link>
      </div>
      <div className="bg-black/40 border border-emerald-500/20 rounded-xl overflow-hidden">
        <table className="w-full">
          <thead className="bg-emerald-900/20">
            <tr>
              <th className="text-left px-6 py-3 text-emerald-400">Nama</th>
              <th className="text-left px-6 py-3 text-emerald-400">Mulai</th>
              <th className="text-left px-6 py-3 text-emerald-400">Selesai</th>
              <th className="text-left px-6 py-3 text-emerald-400">Lokasi</th>
              <th className="text-left px-6 py-3 text-emerald-400">Aksi</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-emerald-500/10">
            {kegiatan.map((item) => (
              <tr key={item.id} className="hover:bg-emerald-900/10">
                <td className="px-6 py-4 text-emerald-100/80">{item.nama}</td>
                <td className="px-6 py-4 text-emerald-100/80">
                  {new Date(item.tanggalMulai).toLocaleDateString("id-ID")}
                </td>
                <td className="px-6 py-4 text-emerald-100/80">
                  {item.tanggalSelesai ? new Date(item.tanggalSelesai).toLocaleDateString("id-ID") : "-"}
                </td>
                <td className="px-6 py-4 text-emerald-100/80">{item.lokasi || "-"}</td>
                <td className="px-6 py-4">
                  <Link href={`/admin/kegiatan/${item.id}/edit`} className="text-emerald-400 hover:text-emerald-300 text-sm">Edit</Link>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

