  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState<Ustadz>({
    id: params.id,
    nama: "",
    spesialisasi: "",
    bio: "",
    foto: "",
  });

  useEffect(() => {
    fetchUstadz();
  }, [params.id]);

  const fetchUstadz = async () => {
    try {
      const res = await fetch(`/api/admin/ustadz/${params.id}`);
      if (res.ok) {
        const data = await res.json();
        setFormData(data);
      }
    } catch (error) {
      console.error("Error fetching ustadz:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);

    try {
      const res = await fetch(`/api/admin/ustadz/${params.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (res.ok) {
        router.push("/admin/ustadz");
      } else {
        alert("Gagal mengupdate ustadz");
      }
    } catch (error) {
      console.error("Error:", error);
      alert("Terjadi kesalahan");
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <div className="text-emerald-100/50">Memuat...</div>;
  }

