"use client";

import { useState, useEffect, useRef } from "react";

const PRAYER_TIMES = [
  { name: "Imsak", key: "imsak" },
  { name: "Subuh", key: "subuh" },
  { name: "Terbit", key: "terbit" },
  { name: "Dhuha", key: "dhuha" },
  { name: "Zuhur", key: "zuhur" },
  { name: "Ashar", key: "ashar" },
  { name: "Maghrib", key: "maghrib" },
  { name: "Isya", key: "isya" },
];

const ADZAN_AUDIO = "https://everyayah.com/data/adzan.mp3";

export default function AdzanWidget() {
  const [jadwal, setJadwal] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [lokasi, setLokasi] = useState("Jakarta");
  const [adzanEnabled, setAdzanEnabled] = useState(true);
  const [playing, setPlaying] = useState(false);
  const [lastPlayedPrayer, setLastPlayedPrayer] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    fetchJadwal();
  }, [lokasi]);

  useEffect(() => {
    if (typeof window !== "undefined") {
      audioRef.current = new Audio(ADZAN_AUDIO);
      audioRef.current.addEventListener("ended", () => setPlaying(false));
      return () => {
        if (audioRef.current) {
          audioRef.current.pause();
          audioRef.current = null;
        }
      };
    }
  }, []);

  const fetchJadwal = async () => {
    setLoading(true);
    try {
      const today = new Date().toISOString().split("T")[0];
      const res = await fetch(
        `/api/jadwal?tanggal=${today}&lokasi=${encodeURIComponent(lokasi)}`
      );
      if (res.ok) {
        const data = await res.json();
        setJadwal(data);
      }
    } catch (error) {
      console.error("Failed to fetch jadwal:", error);
    } finally {
      setLoading(false);
    }
  };

  const getCurrentPrayer = () => {
    if (!jadwal) return null;
    const now = new Date();
    const currentTime = now.getHours() * 60 + now.getMinutes();

    const times = PRAYER_TIMES.map((p) => {
      const [hours, minutes] = jadwal[p.key]?.split(":") || [0, 0];
      return {
        ...p,
        minutes: parseInt(hours) * 60 + parseInt(minutes),
      };
    });

  for (let i = times.length - 1; i >= 0; i--) {
    if (currentTime >= times[i].minutes) {
      return times[i];
    }
  }
  return times[0];
};

const currentPrayer = getCurrentPrayer();

// Auto-play adzan when prayer time matches
useEffect(() => {
  if (!adzanEnabled || !currentPrayer || !jadwal) return;

  const now = new Date();
  const currentTime = now.getHours() * 60 + now.getMinutes();
  const [hours, minutes] = jadwal[currentPrayer.key]?.split(":") || ["0", "0"];
  const prayerMinutes = parseInt(hours) * 60 + parseInt(minutes);

  // If current time matches prayer time and we haven't played it yet
  if (
    currentTime === prayerMinutes &&
    lastPlayedPrayer !== currentPrayer.key &&
    audioRef.current
  ) {
    audioRef.current.currentTime = 0;
    audioRef.current.play().then(() => {
      setPlaying(true);
      setLastPlayedPrayer(currentPrayer.key);
    }).catch((err) => {
      console.error("Failed to play adzan:", err);
    });
  }

  // Reset lastPlayedPrayer when time changes
  if (lastPlayedPrayer && currentTime !== prayerMinutes) {
    setLastPlayedPrayer(null);
  }
}, [currentPrayer, jadwal, adzanEnabled, lastPlayedPrayer]);

const toggleAdzan = () => {
  if (audioRef.current) {
    if (playing) {
      audioRef.current.pause();
      setPlaying(false);
    } else {
      audioRef.current.currentTime = 0;
      audioRef.current.play().then(() => setPlaying(true)).catch(() => {});
    }
  }
  setAdzanEnabled(!adzanEnabled);
};

return (
  <div className="bg-black/40 border border-emerald-500/20 rounded-xl p-6 emerald-glow">
    <h3 className="text-gold font-semibold mb-4 flex items-center gap-2">
      <span>🕌</span> Jadwal Shalat
    </h3>

    {/* Lokasi selector */}
    <div className="mb-4">
      <select
        value={lokasi}
        onChange={(e) => setLokasi(e.target.value)}
        className="w-full bg-black/40 border border-emerald-500/30 rounded-lg px-3 py-2 text-emerald-100 text-sm focus:outline-none focus:border-emerald-400"
      >
        <option value="Jakarta">Jakarta</option>
        <option value="Bandung">Bandung</option>
        <option value="Surabaya">Surabaya</option>
        <option value="Medan">Medan</option>
        <option value="Makassar">Makassar</option>
        <option value="Semarang">Semarang</option>
        <option value="Palembang">Palembang</option>
        <option value="Denpasar">Denpasar</option>
      </select>
    </div>

      {loading ? (
        <div className="text-center text-emerald-100/50 py-8">
          Memuat jadwal...
        </div>
      ) : jadwal ? (
        <>
          <div className="grid grid-cols-4 gap-2 mb-4">
            {PRAYER_TIMES.map((prayer) => {
              const isActive = currentPrayer?.key === prayer.key;
              return (
                <div
                  key={prayer.key}
                  className={`text-center p-2 rounded-lg transition ${
                    isActive
                      ? "bg-emerald-600/30 border border-emerald-500/50"
                      : "bg-black/20"
                  }`}
                >
                  <div className="text-xs text-emerald-200/60 mb-1">
                    {prayer.name}
                  </div>
                  <div
                    className={`text-sm font-mono font-bold ${
                      isActive ? "text-emerald-400" : "text-emerald-100"
                    }`}
                  >
                    {jadwal[prayer.key] || "-"}
                  </div>
                </div>
              );
            })}
          </div>

          {/* Adzan toggle */}
          <div className="flex items-center justify-between pt-3 border-t border-emerald-500/20">
            <div className="flex items-center gap-2">
              <span className="text-emerald-200/60 text-sm">Suara Adzan</span>
              {playing && (
                <span className="text-xs text-emerald-400 animate-pulse">
                  🔊 Playing
                </span>
              )}
            </div>
            <button
              onClick={toggleAdzan}
              className={`relative inline-flex h-5 w-9 items-center rounded-full transition ${
                adzanEnabled ? "bg-emerald-600" : "bg-gray-600"
              }`}
            >
              <span
                className={`inline-block h-3 w-3 transform rounded-full bg-white transition ${
                  adzanEnabled ? "translate-x-5" : "translate-x-1"
                }`}
              />
            </button>
          </div>
        </>
      ) : (
        <div className="text-center text-emerald-100/50 py-8">
          Gagal memuat jadwal
        </div>
      )}
    </div>
  );
}

