import { useState, useEffect } from "react";

export default function ClockWidget() {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString("id-ID", {
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      timeZone: "Asia/Jakarta",
    });
  };

  const formatDate = (date: Date) => {
    return date.toLocaleDateString("id-ID", {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
      timeZone: "Asia/Jakarta",
    });
  };

  return (
    <div className="bg-black/40 border border-emerald-500/20 rounded-xl p-6 emerald-glow">
      <h3 className="text-gold font-semibold mb-4 flex items-center gap-2">
        <span>🕐</span> Waktu Sekarang
      </h3>
      <div className="text-center">
        <div className="text-4xl font-bold text-emerald-400 font-mono mb-2">
          {formatTime(time)}
        </div>
        <div className="text-emerald-100/60 text-sm">{formatDate(time)}</div>
        <div className="text-emerald-200/40 text-xs mt-1">WIB (Asia/Jakarta)</div>
      </div>
    </div>
  );
}

