export default function Kaligrafi() {
  const [quote, setQuote] = useState(KALIGRAFI_QUOTES[0]);

  useEffect(() => {
    const interval = setInterval(() => {
      setQuote((prev) => {
        const currentIndex = KALIGRAFI_QUOTES.findIndex(
          (q) => q.text === prev.text
        );
        const nextIndex = (currentIndex + 1) % KALIGRAFI_QUOTES.length;
        return KALIGRAFI_QUOTES[nextIndex];
      });
    }, 10000);

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="bg-black/40 border border-emerald-500/20 rounded-xl p-8 emerald-glow">
      <div className="text-center">
        <div className="text-gold text-sm mb-4">📜 Kaligrafi Islami</div>
        <p
          className="text-3xl md:text-4xl leading-loose text-emerald-400 mb-6 font-serif"
          dir="rtl"
          lang="ar"
        >
          {quote.text}
        </p>
        <p className="text-emerald-100/70 text-lg mb-2 italic">
          "{quote.translation}"
        </p>
        <p className="text-emerald-200/40 text-sm">{quote.source}</p>
      </div>
    </div>
  );
}

